const cover=p=>p.slug==='bellabelles-egypt'?"<div class=\"bella-card-cover\" style=\"height:clamp(260px,32vw,440px);width:100%;background:var(--cream);overflow:hidden\"><img src=\"assets/bellabelles/carousel/01-cover.jpeg\" alt=\"Which BellaBelles girl are you? The opening slide of Sarah’s completed brand collaboration carousel.\" width=\"1229\" height=\"1536\" loading=\"lazy\" decoding=\"async\" style=\"display:block;width:100%;height:100%;object-fit:contain\"></div>":p.slug==='rhode'?`<div class="rhode-card-cover"><img src="assets/rhode/landing.jpg" alt="Rhode community landing page — independent interface concept" width="1280" height="714" loading="lazy" decoding="async"></div>`:`<div class="cover ${p.theme}" role="img" aria-label="Typographic placeholder for ${p.title}; original artwork pending"><span class="cover-brand">${p.brand}</span><span class="asset-note">LAYOUT PLACEHOLDER</span><div class="cover-title">${p.display}</div><span class="cover-foot">${p.category} / ${p.year}</span></div>`;
const card=p=>{const markup=`<a class="card" href="case-${p.slug}.html" data-project="${p.slug}" data-category="${p.category}">${cover(p)}<div class="meta"><span>${p.category}</span><span>${p.year} ↗</span></div><h3>${p.title}</h3><p>${p.summary}</p><span class="card-button">View full case study ↗</span></a>`;return p.slug==='rhode'?markup.replaceAll('↗','<span class="rhode-arrow" aria-hidden="true">↗</span>'):markup;};
const header=`<div class="wrap"><header class="header"><a class="wordmark" href="index.html">Sarah Safwan<span>Digital Marketing & Creative Specialist</span></a><nav class="nav" aria-label="Main navigation" id="site-navigation">${[['index.html','Home'],['work.html','Work'],['services.html','Services'],['experience.html','Experience'],['cv.html','CV'],['writing.html','Writing'],['calculator.html','Services & Packages'],['contact.html','Contact']].map(([href,label])=>`<a href="${href}" ${href===current?'aria-current="page"':''} ${label==='Contact'?'class="contact"':''}>${label}${label==='Contact'?' <span class="arrow-symbol" aria-hidden="true">↗</span>':''}</a>`).join('')}</nav></header></div>`;
const extraLinks=`<div class="wrap footer-extras"><details><summary>Explore</summary><div>${link('start.html','Start here')}${link('approach.html','My approach')}${link('availability.html','Availability')}${link('collaborate.html','Collaborate')}${link('recruiters.html','For recruiters')}</div></details><details><summary>Project resources</summary><div>${link('build-brief.html','Build your brief')}${link('journey.html','Project journey')}${link('faq.html','Searchable FAQ')}${link('guide.html','Service finder')}${link('compare.html','Compare services')}${link('samples.html','Sample deliverables')}${link('transformations.html','Before & after')}${link('checklist.html','Preparation checklist')}${link('brief.html','Project brief')}</div></details><details><summary>Feedback & information</summary><div>${link('feedback.html','Feedback & reflections')}${link('terms.html','Project terms')}${link('privacy.html','Privacy notice')}</div></details><details><summary>Management</summary><div>${link('feedback-review.html','Feedback review')}${link('enquiries.html','Enquiry inbox')}</div></details></div>`;
const footerNav=`<div class="wrap footer-navigation"><nav aria-label="Footer navigation">${[['index.html','Home'],['work.html','Work'],['services.html','Services'],['experience.html','Experience'],['cv.html','CV'],['writing.html','Writing'],['calculator.html','Services & Packages'],['contact.html','Contact']].map(([href,label])=>`<a href="${href}">${label} <span class="arrow-symbol" aria-hidden="true">↗</span></a>`).join('')}</nav></div>`;
const footer=`<footer class="footer">${footerNav}${extraLinks}<div class="wrap"><a class="wordmark" href="index.html">Sarah Safwan</a><p>Digital Marketing & Creative Specialist</p><a href="https://www.linkedin.com/in/sarahsafwan/" target="_blank" rel="noopener noreferrer" class="eyebrow">LinkedIn <span class="arrow-symbol" aria-hidden="true">↗</span></a><p>© ${new Date().getFullYear()} Sarah Safwan</p></div></footer>`;
const cta=`<section class="cta"><div class="wrap"><div><p class="eyebrow">The next chapter</p><h2>Have something<br><em>in mind?</em></h2></div>${link('contact.html','Let’s work together')}</div></section>`;
const serviceRows=(limit=6)=>services.slice(0,limit).map(([title,desc],i)=>`<a class="service-row" href="service-${i+1}.html"><span class="number">0${i+1}</span><h3>${title}</h3><p>${desc}</p><span class="arrow" aria-label="View service details">↗</span></a>`).join('');
const timeline=()=>experience.map(([date,org,role,desc])=>`<div class="timeline-row"><span class="eyebrow">${date}</span><div><h3>${org}</h3><span class="eyebrow">${role}</span></div><p>${desc}</p></div>`).join('');

const processSection=`<section class="section"><div class="wrap"><p class="eyebrow">Working together</p><h2>From enquiry <em>to delivery.</em></h2><div class="process-grid">${[['01','The enquiry','Tell me about your goals, deliverables, timeline, and budget.'],['02','Scope & agreement','We agree the scope, fee, schedule, revision allowance, and payment terms before work starts.'],['03','Production','I develop the agreed work using the brief and assets provided.'],['04','Review & revisions','You share consolidated feedback. Changes follow the agreed scope and revision allowance.'],['05','Delivery','Final files and any agreed handover materials are delivered in the agreed formats.']].map(([n,t,d])=>`<article><p class="eyebrow">${n}</p><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>`;
const faqSection=`<section class="section faq-section"><div class="wrap"><p class="eyebrow">Before we begin</p><h2>A few <em>practical details.</em></h2><div class="faq-list">${[['How long does a project take?','Turnaround depends on scope, asset readiness, and availability. A delivery schedule is agreed before work begins; fixed turnaround times are not yet published.'],['How many revisions are included?','The number of revision rounds will be stated in your proposal. Additional rounds and changes outside the agreed brief are scoped separately.'],['What are the payment terms?','Payment schedule, currency, deposit, and final-payment terms will be confirmed in the project agreement. Standard terms are still being finalized.'],['What should I provide?','Your brief, audience, objectives, brand references, available assets, required formats, and deadline. For websites, include the page list, content, domain details, and desired functionality.'],['Which files will I receive?','Delivery formats are agreed by service and platform. Editable source files and ownership or usage terms should be specified in the proposal.'],['Do you offer English and Arabic work?','I write in English and Arabic. Bilingual scope, translation, and the review process are agreed for each project.'],['What is included in a website project?','Page count, platform, copywriting, language versions, revisions, and handover are agreed in the brief. Hosting, domains, subscriptions, and ongoing maintenance are quoted separately when needed.'],['Are calculator estimates final quotes?','No. The calculator uses draft rates and planning inputs. Final pricing depends on the agreed scope, availability, and project requirements.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="actions">${link('calculator.html','Plan your project')}${link('contact.html','Ask a question')}</div></div></section>`;

const feedbackSection=`<section class="section feedback-section"><div class="wrap"><p class="eyebrow">Community reflections</p><h2>In their <em>words.</em></h2><p class="lead">Words from people who experienced the work: podcast listeners, readers, and website visitors.</p>${reflectionsGallery()}<div class="actions">${link('feedback.html','Read all reflections')}${link('feedback.html?write=1','Share feedback')}</div></div></section>`;
const certificationGroups=[{provider:'HubSpot Academy',date:'June 2026',items:['Digital Advertising Certified','SEO Certified','Email Marketing Certified','Inbound Certification','Social Media Marketing','Content Marketing Certified']},{provider:'Google',date:'May 2026',items:['Fundamentals of Digital Marketing']}];
const trainingItems=['Social Media Marketing Strategy','Content Creation','Marketing Analytics','Consumer Behaviour','Product Marketing','Strategic Partnerships','AI for Marketing','High-Impact Storytelling'];
const credentialProvider=(provider,date,items)=>`<article class="credential-provider"><header><h3>${provider}</h3><p class="eyebrow">${date}</p></header><ul class="credential-list">${items.map(item=>`<li>${item}</li>`).join('')}</ul></article>`;
const credentialsSection=`<section class="section dark credentials-section"><div class="wrap"><div class="credentials-heading"><p class="eyebrow">Professional development</p><h2>Certifications <em>& training.</em></h2></div><section class="credential-category" aria-label="Certifications"><div class="credential-category-title"><span class="eyebrow">01</span><h3>Certifications</h3></div>${certificationGroups.map(group=>credentialProvider(group.provider,group.date,group.items)).join('')}</section><section class="credential-category" aria-label="Training"><div class="credential-category-title"><span class="eyebrow">02</span><h3>Training</h3></div>${credentialProvider('LinkedIn Learning','July 2026',trainingItems)}</section><section class="credential-language" aria-label="English proficiency"><div><p class="eyebrow">03 / Language proficiency</p><h3>EF SET English Certificate</h3><p>C2 Proficient</p></div><div class="credential-score"><strong>74<span> / 100</span></strong><span class="eyebrow">English</span></div></section><p class="review-note credentials-note">Credential links will be added when available.</p></div></section>`;

const intro=`I work across marketing and creative production. I founded Thy Academia, a study and student mental health blog, where I wrote, designed, and managed social media. My recent work includes campaign concepts and competitor research for a streetwear brand. I’m building my skills in brand identity and web design, and I write in English and Arabic.`;
const titles={'index.html':'Sarah Safwan — Marketing & Creative','work.html':'Selected Work — Sarah Safwan','services.html':'Services — Sarah Safwan','experience.html':'Experience — Sarah Safwan','cv.html':'CV — Sarah Safwan','contact.html':'Contact — Sarah Safwan'};
let content='';
if(page==='index.html')content=`<div class="wrap"><section class="hero reveal"><div class="hero-top"><span class="eyebrow">Digital Marketing & Creative Specialist</span><span class="eyebrow">Portfolio / 2026<br>English</span></div><h1>Campaigns, content,<br>and the work<br><em>behind them.</em></h1><div class="hero-bottom"><div><div class="hero-note"><span>Ideas, shaped into something<br>you can see, read, and use.</span></div><div class="actions">${link('work.html','View my work and CV')}${link('start.html','Start here')}${link('contact.html','Work with me')}</div></div><p class="lead">Across marketing, creative production, and writing. A closer look at the concepts, content, and considered details that make up my work.</p></div></section></div><section class="section dark"><div class="wrap"><div class="section-head"><div><p class="eyebrow">01 / Selected work</p><h2>From idea to <em>execution.</em></h2></div>${link('work.html','Explore all work')}</div><div class="grid">${projects.slice(0,3).map(card).join('')}</div></div></section><section class="section"><div class="wrap intro-grid"><div><p class="eyebrow">02 / A little about me</p><h2>The thinking.<br>The making.<br><em>The person.</em></h2></div><div><p class="lead">${intro}</p><span class="pill">Marketing</span><span class="pill">Creative production</span><span class="pill">Writing</span><div class="actions">${link('experience.html','Explore my experience')}${link('cv.html','View my CV')}</div></div></div></section><section class="section" style="border-top:1px solid #B48A60"><div class="wrap"><div class="section-head"><div><p class="eyebrow">03 / How I can help</p><h2>Good ideas.<br><em>Practical deliverables.</em></h2></div>${link('services.html','All services')}</div><div class="service-list">${serviceRows(3)}</div><p class="eyebrow" style="margin-top:25px">Freelance projects / Rates on request</p></div></section>${feedbackSection}${cta}`;
else if(page==='case-rhode.html'){titles[page]='Rhode — From Influence to Involvement — Sarah Safwan';content=rhodeCase;}
else if(page==='case-bellabelles-egypt.html'){titles[page]='BellaBelles Egypt — Sarah Safwan';content="\u003carticle class=\"bella-case\">\n\u003cdiv class=\"wrap\">\u003cheader class=\"page-hero\">\u003ca class=\"link-arrow\" href=\"work.html\">Back to selected work \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003cp class=\"eyebrow\">Social content &amp; creative production · Completed brand collaboration · 2026\u003c/p>\u003ch1>BellaBelles Egypt\u003c/h1>\u003cp class=\"lead\">For BellaBelles, I created social content that gave the jewelry its own personality. Some pieces leaned into playful, character-led storytelling, while others focused on the products themselves, from styling clips to an animated wishlist.\u003c/p>\u003cdl class=\"bella-facts\">\u003cdiv>\u003cdt>Collaboration\u003c/dt>\u003cdd>BellaBelles Egypt creators program\u003c/dd>\u003c/div>\u003cdiv>\u003cdt>When\u003c/dt>\u003cdd>August–September 2026 · Completed\u003c/dd>\u003c/div>\u003cdiv>\u003cdt>My role\u003c/dt>\u003cdd>Creators program participant · Social content concepting · Visual design and storytelling · Short-form production and editing\u003c/dd>\u003c/div>\u003c/dl>\u003c/header>\n\u003csection class=\"section bella-feature\" aria-labelledby=\"bella-carousel-heading\">\u003cdiv class=\"bella-section-copy\">\u003cp class=\"eyebrow\">01 / Personality carousel\u003c/p>\u003ch2 id=\"bella-carousel-heading\">Which BellaBelles\u003cbr>\u003cem>girl are you?\u003c/em>\u003c/h2>\u003cp class=\"lead\">A five-slide personality carousel that pairs three different moods with a jewelry match.\u003c/p>\u003c/div>\u003cdiv class=\"bella-carousel\" role=\"region\" aria-roledescription=\"carousel\" aria-label=\"Which BellaBelles girl are you? Five-slide carousel\" tabindex=\"0\">\u003cdiv class=\"bella-slides\" id=\"bella-slides\">\n\u003cfigure class=\"bella-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"1 of 5\">\u003cimg src=\"assets/bellabelles/carousel/01-cover.jpeg\" width=\"1229\" height=\"1536\" alt=\"Which BellaBelles girl are you? Cover introducing the jewelry personality carousel.\" decoding=\"async\">\u003c/figure>\n\u003cfigure class=\"bella-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"2 of 5\">\u003cimg src=\"assets/bellabelles/carousel/02-seaside-sweetheart.jpeg\" width=\"1229\" height=\"1536\" alt=\"The Seaside Sweetheart personality, paired with BellaBelles Blush Pony jewelry.\" loading=\"lazy\" decoding=\"async\">\u003c/figure>\n\u003cfigure class=\"bella-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"3 of 5\">\u003cimg src=\"assets/bellabelles/carousel/03-autumn-muse.jpeg\" width=\"1229\" height=\"1536\" alt=\"The Autumn Muse personality, paired with BellaBelles Autumn Cascade jewelry.\" loading=\"lazy\" decoding=\"async\">\u003c/figure>\n\u003cfigure class=\"bella-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"4 of 5\">\u003cimg src=\"assets/bellabelles/carousel/04-golden-girl.jpeg\" width=\"1229\" height=\"1536\" alt=\"The Golden Girl personality, paired with BellaBelles The Whale jewelry.\" loading=\"lazy\" decoding=\"async\">\u003c/figure>\n\u003cfigure class=\"bella-slide\" role=\"group\" aria-roledescription=\"slide\" aria-label=\"5 of 5\">\u003cimg src=\"assets/bellabelles/carousel/05-cta.jpeg\" width=\"1229\" height=\"1536\" alt=\"So… which BellaBelles girl are you? Closing invitation to choose a jewelry personality.\" loading=\"lazy\" decoding=\"async\">\u003c/figure>\n\u003c/div>\u003cdiv class=\"bella-carousel-controls\" hidden>\u003cbutton type=\"button\" class=\"bella-prev\" aria-label=\"Previous carousel slide\" aria-controls=\"bella-slides\">← Previous\u003c/button>\u003cspan class=\"bella-slide-count\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">1 / 5\u003c/span>\u003cbutton type=\"button\" class=\"bella-next\" aria-label=\"Next carousel slide\" aria-controls=\"bella-slides\">Next →\u003c/button>\u003c/div>\u003cp class=\"bella-swipe-hint\">Swipe through the five slides.\u003c/p>\u003c/div>\u003c/section>\n\u003csection class=\"section bella-feature bella-static\" aria-labelledby=\"bella-static-heading\">\u003cdiv class=\"bella-section-copy\">\u003cp class=\"eyebrow\">02 / Static design\u003c/p>\u003ch2 id=\"bella-static-heading\">Fixing pain\u003cbr>\u003cem>as an adult\u003c/em>\u003c/h2>\u003cp class=\"lead\">A playful contrast between a childhood quick fix and a grown-up jewelry pick.\u003c/p>\u003c/div>\u003cfigure>\u003ca href=\"assets/bellabelles/images/fixing-pain-as-an-adult.jpeg\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"View Fixing pain as an adult design at full size in a new tab\">\u003cimg src=\"assets/bellabelles/images/fixing-pain-as-an-adult.jpeg\" width=\"1022\" height=\"1536\" alt=\"BellaBelles static design contrasting ‘Fixing pain as a kid’ with ‘Fixing pain as an adult’ through an accessory-led visual.\" loading=\"lazy\" decoding=\"async\">\u003c/a>\u003cfigcaption>Single static design · \u003ca class=\"link-arrow\" href=\"assets/bellabelles/images/fixing-pain-as-an-adult.jpeg\" target=\"_blank\" rel=\"noopener noreferrer\">View full size \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003c/figcaption>\u003c/figure>\u003c/section>\n\u003csection class=\"section bella-videos\" aria-labelledby=\"bella-video-heading\">\u003cp class=\"eyebrow\">03 / Short-form production\u003c/p>\u003ch2 id=\"bella-video-heading\">Jewelry \u003cem>in motion\u003c/em>\u003c/h2>\u003cp class=\"lead\">Two short styling clips featuring different pieces, alongside a separate animated wishlist.\u003c/p>\u003cdiv class=\"bella-video-grid\">\n\u003cfigure>\u003cvideo controls playsinline preload=\"metadata\" width=\"512\" height=\"910\" poster=\"assets/bellabelles/posters/seahorse-earrings-styling.jpg\" aria-label=\"Seahorse earrings styling video\">\u003csource src=\"assets/bellabelles/videos/seahorse-earrings-styling.mp4\" type=\"video/mp4\">Your browser cannot play this video. \u003ca href=\"assets/bellabelles/videos/seahorse-earrings-styling.mp4\">Open the seahorse earrings styling video\u003c/a>.\u003c/video>\u003cfigcaption>\u003ch3>Seahorse earrings styling\u003c/h3>\u003cp>A seahorse earrings showcase with styling and product close-ups.\u003c/p>\u003ca class=\"link-arrow\" href=\"assets/bellabelles/videos/seahorse-earrings-styling.mp4\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Open seahorse earrings styling video in a new tab\">Open video \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003c/figcaption>\u003c/figure>\n\u003cfigure>\u003cvideo controls playsinline preload=\"metadata\" width=\"512\" height=\"910\" poster=\"assets/bellabelles/posters/autumn-leaf-earrings-styling.jpg\" aria-label=\"Autumn leaf earrings styling video\">\u003csource src=\"assets/bellabelles/videos/autumn-leaf-earrings-styling.mp4\" type=\"video/mp4\">Your browser cannot play this video. \u003ca href=\"assets/bellabelles/videos/autumn-leaf-earrings-styling.mp4\">Open the autumn leaf earrings styling video\u003c/a>.\u003c/video>\u003cfigcaption>\u003ch3>Autumn leaf earrings styling\u003c/h3>\u003cp>A leaf earrings showcase with styling and product close-ups.\u003c/p>\u003ca class=\"link-arrow\" href=\"assets/bellabelles/videos/autumn-leaf-earrings-styling.mp4\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Open autumn leaf earrings styling video in a new tab\">Open video \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003c/figcaption>\u003c/figure>\n\u003cfigure>\u003cvideo controls playsinline preload=\"metadata\" width=\"512\" height=\"640\" poster=\"assets/bellabelles/posters/jewelry-wishlist-animation.jpg\" aria-label=\"Your Jewellery Wishlist Is Here animated video\">\u003csource src=\"assets/bellabelles/videos/jewelry-wishlist-animation.mp4\" type=\"video/mp4\">Your browser cannot play this video. \u003ca href=\"assets/bellabelles/videos/jewelry-wishlist-animation.mp4\">Open the jewelry wishlist animation\u003c/a>.\u003c/video>\u003cfigcaption>\u003ch3>Jewelry wishlist animation\u003c/h3>\u003cp>A separate animated creative: “Your Jewellery Wishlist Is Here!”\u003c/p>\u003ca class=\"link-arrow\" href=\"assets/bellabelles/videos/jewelry-wishlist-animation.mp4\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Open jewelry wishlist animation in a new tab\">Open video \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003c/figcaption>\u003c/figure>\n\u003c/div>\u003c/section>\n\u003cnav class=\"section bella-project-links\" aria-label=\"BellaBelles project links\">\u003ca class=\"link-arrow\" href=\"https://bellabelles.shop/\" target=\"_blank\" rel=\"noopener noreferrer\">Visit BellaBelles Egypt \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003ca class=\"link-arrow\" href=\"https://www.instagram.com/bellabelles.shop/\" target=\"_blank\" rel=\"noopener noreferrer\">BellaBelles on Instagram \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003ca class=\"link-arrow\" href=\"work.html\">Back to selected work \u003cspan aria-hidden=\"true\">↗\u003c/span>\u003c/a>\u003c/nav>\n\u003c/div>\u003c/article>\n";}
else if(page==='brief.html'){titles[page]='Project Brief — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Before the first conversation</p><h1>A clearer brief.<br><em>A better starting point.</em></h1><p class="lead">A short worksheet to gather your goals, audience, deliverables, budget, and timeline before we discuss the project.</p><div class="actions"><a class="button" href="assets/sarah-safwan-project-brief.pdf" download>Download fillable brief ↓</a><a class="link-arrow" href="assets/sarah-safwan-project-brief.txt" download>Download text version ↓</a></div></section><section class="section intro-grid" style="padding-top:0"><div><h2>What to <em>include.</em></h2><ul class="skill-list"><li>Your goals and audience</li><li>Services, deliverables, and formats</li><li>References and available assets</li><li>Website scope and language needs</li><li>Budget, timeline, and handover</li></ul></div><div><p class="lead">Fill in what you know. Leave anything undecided blank; we can work through it together.</p><p class="lead">Save your completed PDF, then attach it to your enquiry email. The text version can be completed in any text editor or copied into the enquiry form.</p><p class="review-note">The worksheet does not set a final price or create a project agreement.</p><div class="actions">${link('contact.html','Start an enquiry')}${link('calculator.html','Explore a draft estimate')}</div></div></section></div>${cta}`;}
else if(page==='enquiries.html'){titles[page]='Enquiry Inbox — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Private portfolio / Enquiry inbox</p><h1>New enquiries,<br><em>clearly organised.</em></h1><p class="lead">Review saved project and recruitment enquiries, including their briefs and draft estimates.</p>${link('contact.html','Back to contact')}</section><section class="section" style="padding-top:0"><p id="enquiry-inbox-status" role="status">Loading enquiries…</p><div id="enquiry-inbox"></div></section></div>`;}
else if(page==='websites.html'){titles[page]='Website Services — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Website services / Scope by agreement</p><h1>A home for<br><em>your work.</em></h1><p class="lead">Explore website project types, then agree the page count, platform, features, content, and handover for your project.</p><p class="review-note">Website skills are developing. Availability, platform suitability, and final scope are confirmed before accepting a project.</p></section><section class="section" style="padding-top:0"><div class="website-service-grid">${[['landing','Landing-page website','A focused page for a campaign, launch, or single offer.'],['portfolio','Portfolio website','A place to introduce your work, experience, services, and contact details.'],['business','Business website','A structured site for your business, services, and enquiries.'],['shop','E-commerce website','An online shop scoped around products, platform, and checkout requirements.']].map(([id,title,description])=>`<a class="website-service-card" href="website-${id}.html"><h2>${title}</h2><p class="lead">${description}</p><span class="card-button">Explore scope & handover ↗</span></a>`).join('')}</div><div class="actions">${link('brief.html','Download a project brief')}${link('calculator.html','Explore a draft estimate')}</div></section></div>${cta}`;}
else if(page.startsWith('website-')){const id=page.replace('website-','').replace('.html','');const website={landing:{title:'Landing-page website',description:'A focused page for a campaign, launch, or single offer.',scope:['Page structure and agreed sections','Responsive layout and supplied content integration','Primary call to action and agreed enquiry links'],handover:'The agreed page, access details, and any included update guidance.'},portfolio:{title:'Portfolio website',description:'A place to introduce your work, experience, services, and contact details.',scope:['Agreed portfolio pages and project templates','Responsive navigation and supplied project content','Contact flow and downloadable files where agreed'],handover:'The agreed site, editable access where supported, and update guidance for portfolio content.'},business:{title:'Business website',description:'A structured site for your business, services, and enquiries.',scope:['Agreed business, service, and contact pages','Responsive navigation and supplied brand/content integration','Agreed enquiry forms and basic page metadata'],handover:'The agreed site, platform access, and guidance for routine content updates.'},shop:{title:'E-commerce website',description:'An online shop scoped around products, platform, and checkout requirements.',scope:['Agreed product and collection structure','Platform setup and supplied product content','Checkout, shipping, and payment requirements agreed in advance'],handover:'Store access and agreed guidance. Product entry limits, integrations, testing, and ongoing support must be specified.'}}[id];if(website){titles[page]=website.title+' — Sarah Safwan';content=`<div class="wrap"><section class="page-hero">${link('websites.html','All website services')}<p class="eyebrow" style="margin-top:35px">Website project / Rates on request</p><h1>${website.title}</h1><p class="lead">${website.description}</p><div class="actions"><a class="button" href="contact.html?service=${id}">Enquire about this website ↗</a>${link('calculator.html','Build a draft estimate')}</div></section><section class="section case-info" style="padding-top:0"><div><p class="eyebrow">Scope first</p><h2>What we <em>agree.</em></h2><p class="review-note">Availability and platform suitability are confirmed before accepting a project.</p></div><div><p class="eyebrow">Possible deliverables</p><ul>${website.scope.map(item=>`<li>${item}</li>`).join('')}</ul><p class="eyebrow">What you provide</p><p>Your brief, page list, brand references, approved copy, images, and any required domain or platform access.</p><p class="eyebrow">Handover</p><p>${website.handover}</p><p class="eyebrow">Quoted separately when needed</p><p>Extra pages, bilingual production, copywriting, integrations, maintenance, and additional revisions. Hosting, domains, paid themes, plugins, and third-party fees are not included unless agreed in writing.</p><p class="review-note">No specific platform, launch date, functionality, or unlimited revisions are promised before the project scope is agreed.</p><div class="actions">${link('brief.html','Download a project brief')}${link('terms.html','Read draft project terms')}</div></div></section></div>${cta}`;}}
else if(page==='recruiters.html'){titles[page]='For Recruiters — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">For recruiters</p><h1>The essentials,<br><em>in one place.</em></h1><p class="lead">Sarah Safwan — Digital Marketing & Creative Specialist. Experience across marketing, creative production, research, and independent publishing.</p><div class="actions"><a class="button" href="assets/Sarah_Safwan_CV_2026.pdf" download>Download draft CV ↓</a>${link('contact.html?type=recruiter','Discuss a role')}</div></section><section class="section recruiter-grid" style="padding-top:0"><article><p class="eyebrow">Current role</p><h2>DAXUEN</h2><p class="lead">Digital Marketing Intern · Remote</p><p>August 2026–present</p><p class="lead">Campaign concepts, creative production, and competitor advertising research.</p></article><article><p class="eyebrow">Skills & working areas</p><ul class="skill-list">${['Content design & production','Editorial planning & writing','Competitor & advertising research','Campaign concepts','Social media management','English writing'].map(t=>`<li>${t}</li>`).join('')}</ul><p class="review-note">Brand identity and web design skills are in development.</p></article><article><p class="eyebrow">Language proficiency</p><h2>English · C2</h2><p class="lead">EF SET English Certificate · 74/100</p><p>Writing in English and Arabic.</p></article><article><p class="eyebrow">Role availability</p><h2>Let’s talk.</h2><p class="lead">${availability.roles}</p><p class="review-note">Role preferences, location requirements, and start date will be discussed directly.</p></article></section><section class="section" style="padding-top:0"><div class="section-head"><h2>Explore <em>the evidence.</em></h2></div><div class="recruiter-links">${link('experience.html','Roles, projects & training')}${link('work.html','Selected work')}${link('cv.html','CV & credentials')}${link('writing.html','Writing & audio')}</div></section></div>${cta}`;}
else if(page==='feedback-review.html'){titles[page]='Feedback Review — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Private portfolio / Feedback review</p><h1>Feedback,<br><em>in one place.</em></h1><p class="lead">Review submissions and publication permissions before approving feedback for the portfolio.</p><div class="actions">${link('feedback.html','Back to client feedback')}</div></section><section class="section" style="padding-top:0"><p id="feedback-review-status" role="status">Loading submissions…</p><div id="feedback-inbox"></div></section></div>`;}
else if(page==='feedback.html'){titles[page]='Feedback & Reflections — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Community reflections</p><h1>In their<br><em>words.</em></h1><p class="lead">Words from people who experienced the work: podcast listeners, readers, and website visitors.</p></section><section class="section" style="padding-top:0">${reflectionsGallery(true)}<p class="review-note imported-source">Previously published on my earlier published work. Original wording, attribution, and ratings retained.</p><div class="intro-grid" style="margin-top:45px"><div><h2>Experienced the work?</h2></div><div><p class="lead">Share your experience of a project, article, podcast, or this website. Choose what may appear on the portfolio.</p><button class="button" type="button" id="feedback-open">Share feedback ↗</button><div class="actions"><a class="link-arrow" href="feedback-review.html">Review submitted feedback ↗</a></div><dialog id="feedback-dialog" class="feedback-dialog" aria-labelledby="feedback-dialog-title" aria-describedby="feedback-dialog-description"><div class="dialog-top"><p class="eyebrow">Your experience</p><button type="button" class="text-button" id="feedback-close">Close ×</button></div><h2 id="feedback-dialog-title">Share your feedback.</h2><p class="review-note" id="feedback-dialog-description">Tell me about the work you experienced. Your feedback is saved privately for review. You choose what may be published.</p><form class="form" id="feedback-form"><div class="enquiry-grid"><div><label for="feedback-name">Your name</label><input id="feedback-name" name="name" autocomplete="name" required maxlength="150" placeholder="Name"></div><div><label for="feedback-email">Email address (optional)</label><input id="feedback-email" name="email" autocomplete="email" type="email" maxlength="254" placeholder="you@example.com"></div></div><label for="feedback-org">Organisation (optional)</label><input id="feedback-org" name="organisation" autocomplete="organization" maxlength="150"><label for="feedback-project">Project, content, or collaboration</label><input id="feedback-project" name="project" required maxlength="200" placeholder="Project, article, podcast, or website"><label for="feedback-service">Service (optional)</label><select id="feedback-service" name="service"><option value="">Not sure yet</option></select><label for="feedback-message">Your feedback</label><textarea id="feedback-message" name="feedback" required minlength="10" maxlength="5000" placeholder="What was the experience like? What did you find useful?"></textarea><fieldset class="feedback-permissions"><legend>Publication permission</legend><label class="checkbox-label"><input id="feedback-publish" type="checkbox">You may publish my feedback on this portfolio</label><label class="checkbox-label"><input id="feedback-publish-name" type="checkbox" disabled>You may publish my name</label><label class="checkbox-label"><input id="feedback-publish-org" type="checkbox" disabled>You may publish my organisation</label><p class="review-note">Without permission, feedback stays private. Your email is never included in the public preview.</p></fieldset><section class="feedback-preview"><p class="eyebrow">Publication preview</p><blockquote id="feedback-preview-text">Your feedback will appear here as you write.</blockquote><p id="feedback-preview-attribution">Anonymous</p><p class="review-note" id="feedback-preview-permission">Private feedback — not for publication.</p></section><button class="button" id="feedback-submit" type="submit">Submit feedback ↗</button><p id="feedback-status" role="status" aria-live="polite"></p></form><section id="feedback-success" hidden><p class="eyebrow">Feedback received</p><h2>Thank you for<br><em>sharing your experience.</em></h2><p class="lead">Your feedback has been saved for review. Nothing is published automatically.</p><p id="feedback-receipt" class="review-note"></p><button type="button" class="button" id="feedback-done">Done</button></section></dialog></div></div></section></div>${cta}`;}
else if(page==='terms.html'){titles[page]='Project Terms — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Project terms / Draft framework</p><h1>Clear expectations.<br><em>Before we begin.</em></h1><p class="lead">The details below identify what will be agreed for each project. Standard policies are still being finalized.</p><span class="pill">Draft — not a finalized agreement</span></section><section class="section terms-list" style="padding-top:0">${[['Scope & schedule','Deliverables, platforms, page or asset counts, responsibilities, milestones, and delivery dates will be specified in the proposal.'],['Payment & currency','The fee, currency, deposit if applicable, payment milestones, invoice terms, and final-payment requirements will be agreed before work begins. No standard deposit or payment deadline has been set here.'],['Cancellations & pauses','Cancellation notice, payment for completed work, treatment of deposits, and any rescheduling or pause arrangements will be agreed in writing. A standard cancellation policy is pending.'],['Revisions & scope changes','Included revision rounds, feedback deadlines, and what counts as a revision will be specified. Changes to the brief or additional work will be discussed and priced before proceeding.'],['Ownership & source files','The agreement will identify final deliverables, editable source files, and when any ownership or licence is granted. No automatic transfer of all working files is promised here.'],['Usage rights & portfolio permission','Permitted channels, duration, territory, exclusivity, third-party asset licences, confidentiality, and permission to show the project in this portfolio will be agreed as relevant.'],['Website handover & third-party costs','Domain ownership, hosting, subscriptions, paid plugins, handover access, maintenance, and support scope will be specified for website projects. Third-party fees are separate unless included in writing.'],['Approval & project agreement','A written project agreement will confirm the final scope and terms before work starts. This draft page is a planning framework, not a substitute for that agreement.']].map(([title,description],i)=>`<article><span class="eyebrow">0${i+1} / To be agreed</span><h2>${title}</h2><p class="lead">${description}</p></article>`).join('')}<div class="actions">${link('contact.html','Discuss project terms')}${link('services.html','Services & FAQs')}</div></section></div>`;}
else if(page==='writing.html'){titles[page]='Writing & Audio — Sarah Safwan';content=`<div class="wrap"><section class="page-hero"><p class="eyebrow">Writing & audio</p><h1>Words, with<br><em>room to think.</em></h1><p class="lead">Editorial writing, personal reflections, and independent conversations. In English and Arabic.</p></section><section class="section" style="padding-top:0"><div class="grid">${projects.filter(p=>['thy-academia','substack','the-sae-talk'].includes(p.slug)).map(card).join('')}</div><div class="reading-list"><h2>Where to <em>read & listen.</em></h2>${[['Medium / Thy Academia','Study life and student mental health.','Publication and selected article links pending.'],['Substack','Personal development and reflections.','Publication and selected article links pending.'],['The Sae Talk','An independent podcast.','Listening platform link pending.']].map(([name,desc,status])=>`<article class="reading-row"><h3>${name}</h3><p>${desc}</p><span class="eyebrow">${status}</span></article>`).join('')}</div></section></div>${cta}`;}
else if(page==='work.html')content=`<div class="wrap"><section class="page-hero reveal"><p class="eyebrow">01 / The portfolio</p><h1>Selected <em>work.</em></h1><p class="lead">Campaign concepts, creative production, research, and writing. Explore the brief, my role, and the work behind each project.</p></section><section class="section" style="padding-top:15px"><div class="filters" role="group" aria-label="Filter projects">${['All work','Creative production','Writing & content','Research','Strategy & experience'].map((f,i)=>`<button type="button" data-filter="${f}" aria-pressed="${i===0}">${f}</button>`).join('')}</div><div class="portfolio-facets"><div><label for="work-industry">Industry / context</label><select id="work-industry"><option value="">All contexts</option><option value="fashion">Fashion</option><option value="education">Education & wellbeing</option><option value="publishing">Independent publishing</option><option value="concept">Campaign concepts</option><option value="beauty">Beauty / skincare</option></select></div><div><label for="work-role">My role</label><select id="work-role"><option value="">All roles</option><option value="creator">Creative production</option><option value="founder">Founder / publisher</option><option value="researcher">Research</option><option value="strategist">Independent strategy</option></select></div><button id="work-reset" class="text-button" type="button">Reset filters</button></div><p id="work-count" role="status">${projects.length} projects</p><div class="grid work-grid" id="project-grid">${[projects.find(p=>p.slug==='rhode'),...projects.filter(p=>p.slug!=='rhode')].map(card).join('')}</div><p class="review-note" style="margin-top:40px">Private portfolio preview. Typographic covers indicate layout only. Original project assets, links, and permissions are being prepared.</p></section></div>${cta}`;
else if(page==='calculator.html'){titles[page]='Services & Packages — Sarah Safwan';content="\u003cdiv id=\"services-packages\">\u003csection class=\"intro wrap\">\u003cp class=\"eyebrow\">SERVICES / PACKAGES\u003c/p>\u003ch1>Good work needs\u003cbr/>\u003cem>the right scope.\u003c/em>\u003c/h1>\u003cp class=\"intro-body\">From an individual campaign to a complete digital presence, here's how we can work together. Choose a service, explore the packages, and tell me what you have in mind.\u003c/p>\u003cp class=\"packages-note\">Prices are starting points for the scope shown. Custom work is quoted on request. Market prices are set separately, not converted using live exchange rates.\u003c/p>\u003cdiv class=\"control-block\">\u003clabel for=\"market\">VIEW PRICES FOR\u003c/label>\u003cselect id=\"market\" aria-label=\"Pricing market\">\u003coption value=\"international_usd\">International · USD\u003c/option>\u003coption value=\"egypt_egp\">Egypt · EGP\u003c/option>\u003coption value=\"lebanon_usd\">Lebanon · USD\u003c/option>\u003c/select>\u003c/div>\u003c/section>\n\u003csection class=\"catalogue\" aria-label=\"Services and packages\">\u003cdiv class=\"catalogue-top\">\u003cp id=\"count\" aria-live=\"polite\">24 SERVICES / 72 PACKAGES\u003c/p>\u003clabel class=\"searchlabel\" for=\"serviceSearch\">FIND A SERVICE \u003cinput id=\"serviceSearch\" type=\"search\" placeholder=\"Search by service or package\" autocomplete=\"off\"/>\u003c/label>\u003c/div>\u003cnav class=\"service-nav\" aria-label=\"Service categories\">\u003cbutton data-filter=\"all\" class=\"active\">All\u003c/button>\u003cbutton data-filter=\"content\">Content & Social\u003c/button>\u003cbutton data-filter=\"strategy\">Strategy & Writing\u003c/button>\u003cbutton data-filter=\"design\">Brand & Design\u003c/button>\u003cbutton data-filter=\"web\">Websites\u003c/button>\u003cbutton data-filter=\"ugc\">UGC\u003c/button>\u003c/nav>\u003cdiv id=\"sections\" aria-busy=\"true\">\u003cp role=\"status\">Loading packages…\u003c/p>\u003c/div>\u003c/section>\n\u003csection class=\"custom wrap\" id=\"custom\">\u003cp class=\"eyebrow\">A DIFFERENT BRIEF?\u003c/p>\u003ch2>Not everything needs\u003cbr/>a package.\u003c/h2>\u003cp>Need a single deliverable, a few extras, or a different mix of services? Individual work and custom projects are quoted on request.\u003c/p>\u003ca id=\"customBtn\" class=\"primary-link\" href=\"contact.html?from=packages&amp;custom=1&amp;market=international_usd\">GET A CUSTOM QUOTE ↗\u003c/a>\u003c/section>\n\u003c/div>";}
else if(page==='services.html')content=`<div class="wrap"><section class="page-hero reveal"><p class="eyebrow">02 / Freelance services</p><h1>Ideas into<br><em>deliverables.</em></h1><p class="lead">Creative and marketing support, from the first concept to files ready to use.</p><span class="pill">Rates on request</span><div class="actions">${link("calculator.html","Build a draft project estimate")}</div></section><section class="section" style="padding-top:0"><div class="service-list">${serviceRows()}</div><div class="intro-grid" style="margin-top:55px"><h2>A clear brief.<br><em>A considered response.</em></h2><div><p class="lead">Tell me what you’re working on, the deliverables you need, and your timeline. We can discuss the scope and rates from there.</p><div class="actions">${link('contact.html','Get in touch')}</div></div></div></section></div><section class="section"><div class="wrap"><p class="eyebrow">Developing offer / Scope by agreement</p><h2>Website <em>projects.</em></h2><p class="lead">Landing pages, portfolios, business sites, and online shops. Availability and scope are confirmed before accepting a project.</p><div class="actions">${link("websites.html","Explore website services")}</div></div></section>${processSection}${faqSection}${feedbackSection}${cta}`;
else if(page==='experience.html')content=`<div class="wrap"><section class="page-hero reveal"><p class="eyebrow">03 / Roles & projects</p><h1>Experience,<br><em>in practice.</em></h1><p class="lead">Marketing, creative production, independent publishing, and research.</p></section><section class="section" style="padding-top:0">${timeline()}<p class="review-note">The Sae Talk began in 2024; current status and end date are awaiting confirmation.</p><div class="actions">${link('cv.html','View and download CV')}</div></section></div>${credentialsSection}${cta}`;
else if(page==='cv.html')content=`<div class="wrap"><section class="page-hero reveal"><p class="eyebrow">04 / Curriculum vitae</p><h1>The work,<br><em>on paper.</em></h1><p class="lead">A concise record of my experience, certifications, training, and languages.</p></section><section class="section" style="padding-top:0"><div class="cv-panel"><div><p class="eyebrow">Sarah Safwan / Digital Marketing & Creative Specialist</p><h2>Curriculum vitae</h2><p>PDF · Draft prepared from the portfolio brief</p></div><a class="button" href="assets/Sarah_Safwan_CV_2026.pdf" download>Download CV ↓</a></div><div class="actions"><a class="link-arrow" href="assets/Sarah_Safwan_CV_2026.pdf" target="_blank" rel="noopener">Open PDF in a new tab ↗</a></div><object class="cv-preview" data="assets/Sarah_Safwan_CV_2026.pdf" type="application/pdf" aria-label="Draft curriculum vitae"><p>Use the download button to view the draft CV.</p></object><p class="review-note">This draft matches the Experience page. The contact address and current podcast dates should be confirmed before sharing publicly.</p><div class="actions">${link('experience.html','Read experience online')}${link('contact.html','Get in touch')}</div></section></div>${credentialsSection}${cta}`;
else if(page==='contact.html')content=`<div class="wrap"><section class="page-hero reveal"><p class="eyebrow">05 / Get in touch</p><h1>Let’s make<br><em>something considered.</em></h1><p class="lead">For freelance projects, marketing opportunities, or a conversation about the work.</p></section><section class="section contact-grid" style="padding-top:10px"><div><h2>Start a conversation.</h2><p class="eyebrow">Email</p><a class="contact-link" href="mailto:sarahsaafwan@gmail.com">sarahsaafwan@gmail.com ↗</a><p class="eyebrow" style="margin-top:35px">Elsewhere</p><a class="contact-link" href="https://www.linkedin.com/in/sarahsafwan/" target="_blank" rel="noopener noreferrer">LinkedIn <span class="arrow-symbol" aria-hidden="true">↗</span></a><div class="contact-availability"><p class="eyebrow">Availability</p><p>${availability.freelance}</p></div><p class="lead" style="font-size:21px;margin-top:35px">A project in mind? Include your scope, timeline, and any useful context.</p></div><form class="form" id="contact-form"><h2>Tell me about your project.</h2><label for="enquiry-type">Enquiry type</label><select id="enquiry-type" name="type"><option value="project">Freelance project</option><option value="recruiter">Recruitment opportunity</option><option value="collaboration">Collaboration proposal</option><option value="general">General enquiry</option></select><label for="name">Your name</label><input id="name" name="name" autocomplete="name" placeholder="Name" maxlength="150" required><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required><label id="enquiry-service-label" for="enquiry-service">Primary service</label><select id="enquiry-service" name="service"><option value="">Not sure yet</option></select><div class="enquiry-grid"><div><label for="budget-min">Budget from (optional)</label><input id="budget-min" name="budgetMin" type="number" min="0" step="0.01" placeholder="Minimum"></div><div><label for="budget-max">Budget to (optional)</label><input id="budget-max" name="budgetMax" type="number" min="0" step="0.01" placeholder="Maximum"></div><div><label for="budget-currency">Budget currency</label><select id="budget-currency" name="currency"><option value="USD">USD</option><option value="EGP">EGP</option><option value="LBP">LBP</option></select></div><div><label for="enquiry-deadline">Preferred deadline (optional)</label><input id="enquiry-deadline" name="deadline" type="date"></div></div><section class="enquiry-estimate" id="enquiry-estimate" hidden><label class="checkbox-label"><input id="include-estimate" name="includeEstimate" type="checkbox" checked>Include my calculator estimate</label><pre id="estimate-preview"></pre><p class="review-note">This is a saved draft estimate. You can return to the calculator to update it before enquiring.</p><a class="link-arrow" href="calculator.html">Update estimate ↗</a></section><fieldset id="enquiry-specific" class="enquiry-specific" hidden><legend id="enquiry-specific-title">A little more context</legend><div id="enquiry-specific-fields"></div></fieldset><label id="enquiry-message-label" for="message">What are you working on?</label><textarea id="message" name="message" placeholder="A little about your project or opportunity…" maxlength="5000" required></textarea><button class="button" id="enquiry-submit" type="submit">Submit enquiry ↗</button><small>Your enquiry is saved privately for review. No email app is required.</small><p>Read the <a href="privacy.html">privacy notice</a> before submitting.</p><button class="text-button" type="button" id="enquiry-download">Download enquiry ↓</button><div class="actions">${link("brief.html","Download a project brief")}${link('build-brief.html','Build your brief')}${link("terms.html","Read draft project terms")}${link("recruiters.html","Recruiter essentials")}</div><p id="form-status" role="status"></p></form></section></div>`;
else if(page.startsWith('service-')){const index=Number(page.match(/service-(\d+)/)?.[1])-1;const service=services[index];const details=[['Design for the feed and beyond','A set of social assets can bring a campaign or content plan into a consistent visual format.','Carousels, posts, stories, and promotional graphics','Share your brand references, platform, copy, and intended formats.'],['From content to finished files','Turn a defined message into a carousel or post sequence with readable layouts and a clear flow.','Finished carousel and post files ready to publish','Share your copy, reference assets, format requirements, and publishing timeline.'],['An edit with a clear direction','Shape existing footage or assets into short-form video for social channels.','Short-form edits using footage or assets you provide','Share the footage, intended duration, platform, references, and key message.'],['Give the content a structure','Organise your ideas around content pillars and a calendar that makes the next steps clear.','Content pillars, calendars, and scheduling plans','Share your audience, goals, channels, and existing content.'],['A direction to build from','Explore campaign ideas and visual approaches before moving into production.','Campaign concepts, moodboards, and visual directions','Share the brief, audience, brand context, and any production constraints.'],['Find useful creative context','Review competitor activity and advertising to support decisions about content and creative direction.','Competitor and advertising analysis','Share your market, competitor set, and the questions you want the research to answer.']][index];if(service){titles[page]=service[0]+' — Sarah Safwan';content=`<div class="wrap"><section class="page-hero">${link('services.html','Back to all services')}<p class="eyebrow" style="margin-top:35px">Service 0${index+1} / Rates on request</p><h1>${service[0]}</h1><p class="lead">${service[1]}</p></section><section class="section case-info" style="padding-top:10px"><div><p class="eyebrow">Freelance support</p><h2>${details[0]}</h2><div class="actions"><a class="button" href="contact.html?service=${index+1}">Enquire about this service ↗</a></div></div><div><p class="eyebrow">The approach</p><p>${details[1]}</p><p class="eyebrow">Possible deliverables</p><p>${details[2]}</p><p class="eyebrow">To get started</p><p>${details[3]}</p><p class="review-note">Scope, timeline, and rates are agreed after the first conversation.</p></div></section><div class="page-navigation">${link('services.html','All six services')}${link('service-'+((index+1)%6+1)+'.html','Next service')}</div></div>${cta}`;}}
else {const p=projects.find(p=>page===`case-${p.slug}.html`);if(p){titles[page]=`${p.title} — Sarah Safwan`;content=`<div class="wrap"><section class="page-hero reveal">${link('work.html','Back to selected work')}<p class="eyebrow" style="margin-top:40px">${p.brand} / ${p.category} / ${p.year}</p><h1>${p.title}</h1><p class="lead">${p.summary}</p></section></div><section class="case-art">${cover(p)}</section><div class="wrap"><section class="section case-info"><dl><dt>Project</dt><dd>${p.brand}</dd><dt>Format</dt><dd>${p.category}</dd><dt>Year</dt><dd>${p.year}</dd>${p.tools?`<dt>Tools</dt><dd>${p.tools}</dd>`:''}</dl><div><p class="eyebrow">The brief</p><h2>The work <em>behind it.</em></h2><p>${p.summary}</p><p class="eyebrow" style="margin-top:35px">My role</p><p>${p.role}</p><p class="eyebrow" style="margin-top:35px">Scope & deliverables</p><ul>${p.scope.map(s=>`<li>${s}</li>`).join('')}</ul></div></section><section class="section" style="padding-top:0"><div class="section-head"><h2>Inside the <em>project.</em></h2><span class="eyebrow">Original assets pending</span></div><div class="asset-grid">${p.assets.map((a,i)=>`<div class="asset-slot"><span>0${i+1} / Asset placeholder</span><strong>${a}</strong><span>Original work to be added</span></div>`).join('')}</div><p class="review-note">${p.status} No performance results are claimed.</p></section><div class="page-navigation">${link("case-"+projects[(projects.indexOf(p)+projects.length-1)%projects.length].slug+".html","Previous project")}${link("work.html","All projects")}${link("case-"+projects[(projects.indexOf(p)+1)%projects.length].slug+".html","Next project")}</div></div>${cta}`;}else content='<div class="wrap"><section class="page-hero"><h1>Page not found.</h1><a class="button" href="index.html">Back to home</a></section></div>';}

