'confirmation.html':['Enquiry Confirmation',resourcePage('Your submission','Enquiry <em>confirmation.</em>','Your latest confirmation is available in the tab where you submitted the enquiry.',`<section id="confirmation-details" class="resource-card"><p id="confirmation-status" role="status">No confirmation is available in this tab. Submit an enquiry to receive a reference.</p><pre id="confirmation-summary" data-no-translate></pre><div class="actions"><button class="button" type="button" id="confirmation-download" hidden>Download submitted details</button><button class="text-button" type="button" id="confirmation-clear" hidden>Clear details from this tab</button></div></section><p class="review-note">A saved enquiry is not a booking or an agreed quote. Availability and scope are confirmed during review.</p>${link('contact.html','Back to enquiries')}`) ],
