if(page.startsWith('case-')||page==='writing.html'){const reading=['case-substack.html','case-thy-academia.html','case-the-sae-talk.html','writing.html'].includes(page);const next=reading?[['approach.html','The thinking behind it','Explore the perspective behind the work.'],['collaborate.html','Create something together','Discuss an editorial or audio collaboration.'],['case-advertising-research.html','A different discipline','Explore marketing research.']]:[['compare.html','Connect work and services','Compare possible support for your own project.'],['samples.html','See possible outputs','Explore clearly labelled personal concepts.'],['build-brief.html','Shape your next project','Turn your requirements into a useful brief.']];content+=`<section class="section explore-next"><div class="wrap"><p class="eyebrow">Keep exploring</p><h2>Explore <em>next.</em></h2>${resourceCards(next)}</div></section>`;}

if(content.includes(cta))content=content.replace(cta,'')+cta;
if(typeof RewrittenPages!=='undefined'&&RewrittenPages[page])content=RewrittenPages[page];
document.title=typeof RewrittenTitles!=='undefined'&&RewrittenTitles[page]||titles[page]||'Sarah Safwan';
document.getElementById('app').innerHTML=header+`<main id="main" tabindex="-1">${content}</main>`+footer;
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button?'true':'false'));document.querySelectorAll('[data-category]').forEach(c=>c.hidden=button.dataset.filter!=='All work'&&c.dataset.category!==button.dataset.filter);}));
const form=document.getElementById('contact-form');if(form&&!document.getElementById('enquiry-service'))form.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(form);const subject='Portfolio enquiry from '+values.get('name');const body=values.get('message')+'\n\nFrom: '+values.get('name')+'\nReply to: '+values.get('email');location.href='mailto:sarahsaafwan@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.getElementById('form-status').textContent='Your email app should open with the message. If it doesn’t, use the email link alongside this form.';});

document.querySelectorAll('[data-feedback-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-feedback-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button?'true':'false'));document.querySelectorAll('[data-reflection-category]').forEach(card=>card.hidden=button.dataset.feedbackFilter!=='all'&&card.dataset.reflectionCategory!==button.dataset.feedbackFilter);}));
document.querySelectorAll('[data-reflection-expand]').forEach(button=>button.addEventListener('click',()=>{const quote=document.getElementById(button.dataset.reflectionExpand);const expanded=button.getAttribute('aria-expanded')==='true';quote.classList.toggle('reflection-collapsed',expanded);button.setAttribute('aria-expanded',expanded?'false':'true');const text=expanded?'Read more':'Read less';button.textContent=text;}));
